// 1. std::fill (Applies value to range [first, last))
std::vector<int> V(8);

// Assign 42 to all elements
std::fill(V.begin(), V.end(), 42);

// Assign 99 to middle elements (indices 2 to 5)
std::fill(V.begin() + 2, V.begin() + 6, 99);


// 2. std::fill_n (Applies value to N elements starting at first)
std::string S(10, ' ');

// Assign 'X' to the first 4 elements
std::fill_n(S.begin(), 4, 'X');

// Assign 'Y' starting at index 5 for 2 elements
std::fill_n(S.begin() + 5, 2, 'Y');
